import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// PROBE (review verification, not a repo test): does collectEntriesForHandoff
/// see the WHOLE branch of a windowed-opened session when the resume budget
/// stops the residency walk early?
void main() {
  test('probe: windowed session branch vs full branch', () async {
    final repo = JsonlSessionRepo(
      fs: MemoryFileSystem(),
      sessionsRoot: '/sessions',
    );
    final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
    // 40 records x ~400-char texts (~100+ estimated tokens each).
    for (var i = 0; i < 40; i++) {
      await session.appendMessage(
        UserMessage.text('message number $i ${'x' * 400}'),
      );
    }
    final full = await session.getBranch();
    // Reopen WINDOWED (the CLI resume path: session_commands.dart:868) and
    // run the same budget-bounded residency walk the resume runs.
    final meta = await session.getMetadata();
    final windowed = await repo.open(meta, windowed: true);
    final residentBefore = await windowed.getBranch();
    await windowed.ensureCompactionBoundaryResident(tokenBudget: 400);
    final resident = await windowed.getBranch();
    // ignore: avoid_print
    print('full branch=${full.length} residentBefore=${residentBefore.length} '
        'residentAfterWalk=${'${resident.length}'} hasOlder='
        '${windowed.getStorage() is WindowedSessionStorage}');
    final entries = await collectEntriesForHandoff(windowed);
    // ignore: avoid_print
    print('collectEntriesForHandoff saw ${entries.length} of ${full.length} '
        'records');
    expect(full.length, 40);
  });
}

