import json, subprocess, sys
d = json.load(open('outputs/pr_review.json'))
# Build right-hand line number sets per file from the full diff
files = {}
for f in {c['path'] for c in d['inlineComments']}:
    out = subprocess.run(['git','diff','origin/main...HEAD','--',f],capture_output=True,text=True).stdout
    rhs=set(); new=None
    for line in out.splitlines():
        if line.startswith('@@'):
            new=int(line.split('+')[1].split(',')[0].split(' ')[0])
        elif line.startswith('+') and not line.startswith('+++'):
            rhs.add(new); new+=1
        elif line.startswith(' '):
            new+=1
    files[f]=rhs
ok=True
for c in d['inlineComments']:
    if c['line'] in files[c['path']]:
        print(f"IN DIFF  {c['path']}:{c['line']}  severity={c['severity']}")
    else:
        ok=False; print(f"MISSING  {c['path']}:{c['line']}")
sys.exit(0 if ok else 1)
EOF

